package ru.hryushki.accounts;
import androidx.test.ext.junit.runners.AndroidJUnit4;import org.junit.*;import org.junit.runner.RunWith;import org.json.*;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class) public class SyncTest {
 JSONObject seed()throws Exception{JSONObject d=SyncModel.attach(Engine.empty(),"u");d.getJSONArray("products").put(new JSONObject("{\"name\":\"Лежанка\",\"HomePrice\":680,\"sku\":\"LZ-001\"}"));SyncModel.ids(d,false);return d;}
 JSONObject reply(SyncModel.Request q,int v,boolean ok)throws Exception{JSONObject r=new JSONObject();r.put("owner","u");r.put("ok",ok);JSONArray a=new JSONArray();for(JSONObject x:q.all.values()){JSONObject n=Engine.copy(x);n.put("version",v);a.put(n);}r.put("records",a);r.put("conflicts",new JSONArray());return r;}
 @Test public void acknowledgementAndOfflineQueue()throws Exception{JSONObject d=seed();SyncModel.Request q=SyncModel.request(d,"u");assertEquals(1,q.changes.length());JSONObject n=SyncModel.merge(d,q,reply(q,1,true),"u");assertEquals(0,SyncModel.request(n,"u").changes.length());}
 @Test public void editsWhileRequestIsInFlight()throws Exception{JSONObject d=seed();SyncModel.Request q=SyncModel.request(d,"u");JSONObject fresh=Engine.copy(d);fresh.getJSONArray("products").getJSONObject(0).put("HomePrice",700);JSONObject n=SyncModel.merge(fresh,q,reply(q,1,true),"u");assertEquals(700,n.getJSONArray("products").getJSONObject(0).getInt("HomePrice"));assertEquals(1,SyncModel.request(n,"u").changes.getJSONObject(0).getInt("base_version"));}
 @Test public void conflictResolutionBothWays()throws Exception{JSONObject d=seed();SyncModel.Request q=SyncModel.request(d,"u");d=SyncModel.merge(d,q,reply(q,1,true),"u");JSONObject local=Engine.copy(d),remote=Engine.copy(d);local.getJSONArray("products").getJSONObject(0).put("HomePrice",710);remote.getJSONArray("products").getJSONObject(0).put("HomePrice",720);JSONObject n=SyncModel.merge(local,SyncModel.request(local,"u"),reply(SyncModel.request(remote,"u"),2,false),"u");assertEquals(1,n.getJSONObject("_sync").getJSONArray("conflicts").length());JSONObject cloud=SyncModel.resolve(n,0,true);assertEquals(720,cloud.getJSONArray("products").getJSONObject(0).getInt("HomePrice"));assertEquals(0,SyncModel.request(cloud,"u").changes.length());JSONObject ours=SyncModel.resolve(n,0,false);assertEquals(710,ours.getJSONArray("products").getJSONObject(0).getInt("HomePrice"));assertEquals(2,SyncModel.request(ours,"u").changes.getJSONObject(0).getInt("base_version"));}
 @Test public void localOperationNumbersAreRenumbered()throws Exception{JSONObject d=SyncModel.attach(Engine.empty(),"u");JSONObject op=new JSONObject("{\"id\":1,\"date\":\"03.11.2026\",\"type\":\"Расход\",\"item\":\"Тест\",\"qty\":0,\"amount\":10}");d.getJSONArray("operations").put(op);SyncModel.ids(d,false);JSONObject other=Engine.copy(d);other.getJSONArray("operations").getJSONObject(0).put("_syncId","other-id");JSONObject n=SyncModel.merge(d,SyncModel.request(d,"u"),reply(SyncModel.request(other,"u"),1,true),"u");assertEquals(2,n.getJSONArray("operations").length());assertNotEquals(n.getJSONArray("operations").getJSONObject(0).getInt("id"),n.getJSONArray("operations").getJSONObject(1).getInt("id"));}
 @Test public void loginSecretsAreNotPartOfDatabase()throws Exception{JSONObject d=seed();String json=d.toString();assertFalse(json.contains("refresh_token"));assertFalse(json.contains("password"));}
}
